use super::*;
use crate::schema::scene_preparation::{DocumentVectorJob,DocumentSceneLimits,DocumentAlgorithmLimits};
fn rows()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap()}
fn scene(name:&str)->PreparedScene{
 let rows:serde_json::Value=serde_json::from_str(include_str!("../../../../../📋️prepare/🧫️fixtures/🎬️vector/🔣️.json")).unwrap();let row=rows.as_array().unwrap().iter().find(|r|r["name"]==name).unwrap();let document=serde_json::from_value(row["document"].clone()).unwrap();
 let algorithms=DocumentAlgorithmLimits{max_work:1000000000,trace:crate::schema::scene_trace::DocumentTraceLimits{max_pixels:16777216,max_admitted_pixels:67108864,max_source_bytes:268439552,max_edges:65536,max_segments:65536,max_retained_segments:65536,max_work:1000000000},booleans:crate::schema::scene_booleans::DocumentBooleanLimits{tolerance:0.005,epsilon:1e-8,max_depth:32,max_references:32768,max_edges:65536,max_parameters:262144,max_atomic_edges:65536,max_segments:65536,max_retained_segments:262144,max_work:1000000000}};
 let mut producer=DocumentVectorJob::new(&document,DocumentSceneLimits{max_nodes:1024,max_depth:32,max_segments:65536,max_references:32768,max_source_bytes:268439552},algorithms).unwrap();while !producer.advance(4096).unwrap().done{}let(mut close,plan)=producer.into_retirement();while !close.advance(4096).unwrap().done{}
 let mut producer=super::super::ScenePaintJob::new(plan.unwrap(),0.001,super::super::PaintedSceneLimits{max_nodes:1024,max_segments:65536,max_points:262144,max_contours:65536,max_work:1000000000});while !producer.advance(4096).unwrap().done{}let(mut close,scene)=producer.into_retirement();while !close.advance(4096).unwrap().done{}scene.unwrap()
}
fn identity()->PreparedSceneIdentity{PreparedSceneIdentity{source:SceneIdentity{instance:710034,base:9007199254740993,generation:u64::MAX,revision:[3;32]},build:9007199254740993,flatness:0.001}}
fn query(row:&serde_json::Value)->PreparedScenePick{let q=&row["query"];match q["kind"].as_str().unwrap(){"point"=>PreparedScenePick::Point{point:serde_json::from_value(q["point"].clone()).unwrap(),tolerance:q["tolerance"].as_f64().unwrap(),required_flatness:q["requiredFlatness"].as_f64().unwrap()},"rectangle"=>PreparedScenePick::Rectangle{start:serde_json::from_value(q["start"].clone()).unwrap(),end:serde_json::from_value(q["end"].clone()).unwrap(),crossing:q["crossing"].as_bool().unwrap()},_=>PreparedScenePick::Lasso{points:serde_json::from_value(q["points"].clone()).unwrap()}}}
fn close(scene:PreparedScene){let mut close=super::super::PreparedSceneCloseJob::new(scene);while !close.advance(4096).unwrap().done{}assert!(close.terminal_is_empty());}
#[test]
fn prepared_scene_picking_uses_actual_resolved_paint_front_to_back_under_every_grant(){for row in rows().as_array().unwrap(){for grant in [1,7,4096]{let scene=scene(row["source"].as_str().unwrap());let pointer=scene.geometry.as_ptr();let mut job=PreparedScenePickJob::new(identity(),query(row),256).unwrap();let(mut work,mut done)=(0,false);assert!(job.result(identity()).is_err());for _ in 0..2000000{let p=job.advance(&scene,identity(),grant).unwrap();assert!(p.work>work&&p.work-work<=grant as u64);work=p.work;if p.done{done=true;break;}}assert!(done);let ids=job.result(identity()).unwrap().iter().map(|index|scene.plan.nodes[*index].id.as_str()).collect::<Vec<_>>();assert_eq!(serde_json::to_value(ids).unwrap(),row["expected"],"{}",row["source"]);assert_eq!(scene.geometry.as_ptr(),pointer);close(scene);}}eprintln!("[DEBUG] Native complete-cache scene picks matched all neutral front-to-back point/rectangle/lasso queries without geometry copies");}
#[test]
fn prepared_scene_query_refuses_pending_stale_cancelled_capacity_and_precision(){let scene=scene("shared asset geometry");let query=PreparedScenePick::Rectangle{start:[-1.0,-1.0],end:[3.0,2.0],crossing:false};let mut job=PreparedScenePickJob::new(identity(),query.clone(),1).unwrap();assert!(job.advance(&scene,identity(),4096).unwrap_err().contains("capacity"));assert!(job.result(identity()).is_err());for grant in [0,9007199254740992]{assert!(PreparedScenePickJob::new(identity(),query.clone(),256).unwrap().advance(&scene,identity(),grant).is_err());}let mut job=PreparedScenePickJob::new(identity(),query.clone(),256).unwrap();job.advance(&scene,identity(),1).unwrap();job.cancel();assert!(job.advance(&scene,identity(),1).is_err());assert!(job.result(identity()).is_err());let mut job=PreparedScenePickJob::new(identity(),query,256).unwrap();job.advance(&scene,identity(),1).unwrap();assert!(job.advance(&scene,PreparedSceneIdentity{build:identity().build-1,..identity()},1).unwrap_err().contains("authority"));assert!(job.result(identity()).is_err());assert!(PreparedScenePickJob::new(identity(),PreparedScenePick::Point{point:[0.0,0.0],tolerance:0.0,required_flatness:0.0005},256).is_err());close(scene);}
#[test]
fn cached_selection_bounds_share_unlocked_selected_group_prefix(){let mut scene=scene("group full affine");assert_eq!(prepared_selection_bounds(&scene,&["group".into()]).unwrap(),Some([22.0,34.0,27.0,37.0]));assert_eq!(prepared_selection_bounds(&scene,&["child".into()]).unwrap(),Some([22.0,34.0,27.0,37.0]));scene.plan.nodes[1].locked_ancestors=2;assert_eq!(prepared_selection_bounds(&scene,&["group".into()]).unwrap(),Some([22.0,34.0,27.0,37.0]));assert!(prepared_selection_bounds(&scene,&["child".into()]).unwrap().is_none());close(scene);}
#[test]
fn prepared_scene_crossing_query_refuses_interrupted_boundary_work(){let rows=rows();let row=rows.as_array().unwrap().iter().find(|r|r["query"]["kind"]=="rectangle"&&r["query"]["crossing"]==true&&r["expected"].as_array().unwrap().is_empty()).unwrap();let mut scene=scene(row["source"].as_str().unwrap());let pointer=scene.geometry.as_ptr();for action in ["cancel","build","precision"]{let mut job=PreparedScenePickJob::new(identity(),query(row),256).unwrap();while job.advance(&scene,identity(),1).unwrap().phase!="paint"{}assert!(!job.advance(&scene,identity(),20).unwrap().done);assert!(job.result(identity()).is_err());if action=="cancel"{job.cancel();}let live=if action=="build"{PreparedSceneIdentity{build:identity().build-1,..identity()}}else{identity()};if action=="precision"{scene.flatness=0.002;}let error=job.advance(&scene,live,1).unwrap_err();assert!(error.contains(action)||action=="build"&&error.contains("authority"));scene.flatness=0.001;assert!(job.result(identity()).is_err());assert_eq!(scene.geometry.as_ptr(),pointer);}close(scene);eprintln!("[DEBUG] Native crossing boundary work refuses cancellation and cache authority changes without partial selection");}
#[test]
fn prepared_scene_lasso_query_refuses_interrupted_segment_work(){let rows=rows();let row=rows.as_array().unwrap().iter().find(|r|r["source"]=="group full affine"&&r["query"]["kind"]=="lasso"&&!r["expected"].as_array().unwrap().is_empty()).unwrap();let mut scene=scene(row["source"].as_str().unwrap());let pointer=scene.geometry.as_ptr();for action in ["cancel","build","precision"]{let mut job=PreparedScenePickJob::new(identity(),query(row),256).unwrap();while job.advance(&scene,identity(),1).unwrap().phase!="paint"{}assert!(!job.advance(&scene,identity(),20).unwrap().done);assert!(job.result(identity()).is_err());if action=="cancel"{job.cancel();}let live=if action=="build"{PreparedSceneIdentity{build:identity().build-1,..identity()}}else{identity()};if action=="precision"{if let PreparedPaint::Path(regions)=&mut scene.geometry[1].paint{regions.flatness=0.002;}}let error=job.advance(&scene,live,1).unwrap_err();assert!(error.contains(action)||action=="build"&&error.contains("authority"));if let PreparedPaint::Path(regions)=&mut scene.geometry[1].paint{regions.flatness=0.001;}assert!(job.result(identity()).is_err());assert_eq!(scene.geometry.as_ptr(),pointer);}close(scene);eprintln!("[DEBUG] Native borrowed lasso partitions refuse cancellation, changed build and painted-entry precision without partial selection");}
#[test]
fn prepared_scene_lasso_interior_refuses_late_cancelled_stale_and_imprecise_queries(){
 let rows=rows();let row=rows.as_array().unwrap().iter().find(|r|r["name"]=="twice traced island cancels").unwrap();let mut scene=scene(row["source"].as_str().unwrap());let pointer=scene.geometry.as_ptr();let mut complete=PreparedScenePickJob::new(identity(),query(row),256).unwrap();let work=loop{let progress=complete.advance(&scene,identity(),1).unwrap();if progress.done{break progress.work;}};assert_eq!(complete.result(identity()).unwrap(),&[1]);assert!(work>32);
 for action in ["cancel","build","precision"]{let mut job=PreparedScenePickJob::new(identity(),query(row),256).unwrap();let progress=job.advance(&scene,identity(),(work-16)as usize).unwrap();assert_eq!(progress.phase,"paint");assert!(!progress.done);assert!(job.result(identity()).is_err());if action=="cancel"{job.cancel();}let live=if action=="build"{PreparedSceneIdentity{build:identity().build-1,..identity()}}else{identity()};if action=="precision"{let PreparedPaint::Path(regions)=&mut scene.geometry[1].paint else{panic!("path required")};regions.flatness=0.002;}let error=job.advance(&scene,live,1).unwrap_err();assert!(error.contains(if action=="build"{"authority"}else{action}));if let PreparedPaint::Path(regions)=&mut scene.geometry[1].paint{regions.flatness=0.001;}assert!(job.result(identity()).is_err());assert_eq!(scene.geometry.as_ptr(),pointer);}
 close(scene);eprintln!("[DEBUG] Native late lasso interior refused cancellation, build and painted-entry precision after {} grants without publishing partial hits",work-16);
}
